mapper.select:
SELECT t.bookSetId, t.prodId, t.valDate, MAX(case when t.DETAIL_DIST = '02' and t.MARKET_VALUE is not null then t.MARKET_VALUE end) AS prodAllAmt, MAX(case when t.DETAIL_DIST = '38' and t.MARKET_VALUE is not null then t.MARKET_VALUE end) AS nowDayProfitValue, MAX(case when t.DETAIL_DIST = '41' and t.MARKET_VALUE is not null then t.MARKET_VALUE end) AS nowDayRate, MAX(case when t.DETAIL_DIST = '43' and t.MARKET_VALUE is not null then t.MARKET_VALUE end) AS totalRate, MAX(case when t.DETAIL_DIST = '45' and t.MARKET_VALUE is not null then t.MARKET_VALUE end) AS sevenDayRate, MAX(case when t.DETAIL_DIST = '06' and t.MARKET_VALUE is not null then t.MARKET_VALUE end) AS dailyAllDebt, MAX(case when t.DETAIL_DIST = '05' and t.MARKET_VALUE is not null then t.MARKET_VALUE end) AS dailyAssetAllValue, MAX(case when t.DETAIL_DIST = '02' and t.MARKET_VALUE is null then t.SUBJECT_NAME end) AS prodAllAmtStr, MAX(case when t.DETAIL_DIST = '38' and t.MARKET_VALUE is null then t.SUBJECT_NAME end) AS nowDayProfitValueStr, MAX(case when t.DETAIL_DIST = '41' and t.MARKET_VALUE is null then t.SUBJECT_NAME end) AS nowDayRateStr, MAX(case when t.DETAIL_DIST = '43' and t.MARKET_VALUE is null then t.SUBJECT_NAME end) AS totalRateStr, MAX(case when t.DETAIL_DIST = '45' and t.MARKET_VALUE is null then t.SUBJECT_NAME end) AS sevenDayRateStr, MAX(case when t.DETAIL_DIST = '06' and t.MARKET_VALUE is null then t.SUBJECT_NAME end) AS dailyAllDebtStr, MAX(case when t.DETAIL_DIST = '05' and t.MARKET_VALUE is null then t.SUBJECT_NAME end) AS dailyAssetAllValueStr FROM ( SELECT DETAIL_DIST, BOOKSET_ID AS bookSetId, (SELECT bb.ACCT_SUBJECT_ID FROM BOK_BOOKSET bb WHERE bb.BOOKSET_ID = BOK_VAL_TABLE_DATA.BOOKSET_ID) AS prodId, TO_CHAR(VAL_DATE,'YYYY-MM-DD') AS valDate, MARKET_VALUE, SUBJECT_NAME FROM BOK_VAL_TABLE_DATA WHERE BOOKSET_ID IN (SELECT bookset_id FROM BOK_BOOKSET WHERE ACCT_MODE = '03') AND BOOKSET_ID in
#{item, jdbcType=VARCHAR}
AND VAL_DATE = #{exeDate, jdbcType=TIMESTAMP} AND DETAIL_DIST IN ('02','38','41','43','45','06','05') ) t GROUP BY t.bookSetId,t.prodId,t.valDate
